/**
 * engine/samples/template.ts — **新建空白谱的模板文本**（唯一来源，纯常量）
 *
 * 用户 2026-10 要求（清单 B7）：「预览渲染、播放、源码格式化、源码高亮、错误信息显示提示等
 * 共性的功能都可以独立到引擎层面」，且「应用端也应同样处理」。
 *
 * 现状：这份文本在应用是**一个文件**（`src/samples/未命名.jps`，adj481 的"文件驱动"设计：
 * 改那个文件即改新建出来的空白谱），在 Obsidian 插件是 `src/newFile.ts` 里的字符串常量 ——
 * 两处内容当时**逐字节相同**（已核对），但没有任何机制保证以后还相同。
 *
 * 处理：真源放引擎（这里），两端各自保持自己的形态但被**机器闸门**钉住 ——
 *  · 插件：直接 import 本常量（删掉自己的副本）；
 *  · 应用：保留 `src/samples/未命名.jps` 文件（便于在仓库里看见/编辑），
 *    由冒烟断言 `文件内容 === DEFAULT_NEW_JPS_TEMPLATE` ⇒ 谁改了一边而没改另一边就红灯。
 */
export const DEFAULT_NEW_JPS_TEMPLATE = `#===========描述头定义===========
V: 1.0
B: 未命名
Z: 佚名 词曲
D: C
P: 4/4
S: 本乐谱使用「爱记谱 https://ijipu.pages.dev」编制
#==========以下为简谱主体==========
Q: 1 2 3 4 |
C: 这是歌词





#===以下为页面设置，请勿手动修改===
# jps-config:{}
`

/** 新建文件的默认基名（应用/插件都用它拼「未命名[ n].jps」） */
export const DEFAULT_NEW_JPS_BASE = '未命名'

/** 谱面源码扩展名（两端一致） */
export const JPS_EXT = '.jps'
